"""Private vector/meta-fit preparation only. No network, basefit, features or calibration."""
from pathlib import Path
import os,json,time,signal,shutil,importlib.util,importlib.metadata
import numpy as np,pandas as pd
from scipy.stats import spearmanr,pearsonr
from .private_p1 import T,sha,save,require,scores
from .private_p5 import mix,fixed_map
from .admet_full_math import blend_weight
ROOT=Path(__file__).resolve().parents[1]

def main():
 os.umask(0o077);start=time.monotonic();c=json.loads((ROOT/'private_candidate_config.json').read_text());signal.signal(signal.SIGALRM,lambda *args:(_ for _ in ()).throw(TimeoutError('Candidate10minute cap')));signal.alarm(c['timeout_seconds']);out=Path(c['output_dir']);out.mkdir(parents=True,exist_ok=False);require(sha(c['manifest']['path'])==c['manifest']['sha256'],'Manifest changed');require(sha(ROOT/'official_scoring_functions.py')==c['scorer_sha256'],'Scorer changed');m=json.loads(Path(c['manifest']['path']).read_text());files=m['files']
 for name,r in files.items():require(sha(r['path'])==r['sha256'],'Input changed:'+name)
 train=pd.read_csv(files['official_train']['path']).set_index('Molecule_Name');blind=pd.read_csv(files['official_blind']['path']);require(len(train)==4905 and len(blind)==750 and set(blind)=={'Molecule_Name','SMILES'} and not set(train.index)&set(blind.Molecule_Name),'Training/blind identity boundary');trids=train.index.tolist();qids=blind.Molecule_Name.tolist()
 def matrix(key,ids,smiles):
  d=pd.read_csv(files[key]['path']).set_index('Molecule_Name');require(d.index.is_unique and d.index.tolist()==ids,'Exact ID/order mismatch:'+key);require(d.SMILES.tolist()==list(smiles),'SMILES mismatch:'+key);a=d[T].to_numpy(float);require(np.isfinite(a).all(),'Nonfinite matrix:'+key);return a
 N=matrix('original_full_OOF',trids,train.SMILES);H=matrix('H6_feature_full_OOF',trids,train.SMILES);Y=train[T].to_numpy(float);L=train[[x+'_conf_low' for x in T]].to_numpy(float);U=train[[x+'_conf_high' for x in T]].to_numpy(float);selection=json.loads(Path(files['blind_weights']['path']).read_text());oldw=np.asarray(selection['chosen']['weight']);require(selection['chosen']['params']=={'num_leaves':15,'max_depth':4},'Wrong frozen H6 head');historical_N=matrix('historical_corrected_full_OOF',trids,train.SMILES);historical_H6=matrix('historical_H6_selected_full_OOF',trids,train.SMILES);historical_OOF=mix(historical_N,H,oldw,True);require(np.allclose(historical_OOF,historical_H6,atol=1e-12,rtol=0),'H6 feature OOF mismatch');hscore=scores(Y,H,L,U)
 for target in T:require(abs(hscore['per_cyp'][target]['ST_RAE']-selection['chosen']['fit_details']['per_target_fit'][target]['extra_training_OOF_ST_RAE'])<1e-12,'Wrong feature-only full OOF')
 weights=[];fit={}
 for j,target in enumerate(T):
  weight,receipt=blend_weight(Y[:,j:j+1],N[:,j:j+1],H[:,j:j+1],L[:,j:j+1],U[:,j:j+1]);require(0<=weight<=1,'Nonconvex weight');receipt['fit_scope']='full official training OOF only; final coefficient fit, not independent validation';weights.append(weight);fit[target]=receipt
 weights=np.asarray(weights);coef={'feature_weight_convention':'(1-w)*ORIGINAL native + w*same frozen H6 feature-only expert','weights':dict(zip(T,weights.tolist())),'training_fit':fit,'observed_label_counts':dict(zip(T,np.isfinite(Y).sum(0).tolist())),'no_blind_labels_used':True,'no_new_base_fit_feature_or_calibration':True,'H6_params_frozen':selection['chosen']['params']};save(out/'COEFFICIENTS.json',coef)
 original=matrix('blind750_original_raw',qids,blind.SMILES);incumbent=matrix('blind750_original_served',qids,blind.SMILES);badlast=matrix('bad_last_submission',qids,blind.SMILES);corr=matrix('blind750_corrected_raw',qids,blind.SMILES);historical_raw=matrix('blind750_H6_raw',qids,blind.SMILES);heads=[]
 for target in T:
  r=json.loads(Path(files['receipt_'+target]['path']).read_text());require(r['predictions_sha256']==files['head_'+target]['sha256'] and r['identity']['params']==selection['chosen']['params'] and r['reload_exact'],'Head provenance');v=np.load(files['head_'+target]['path'],allow_pickle=False);require(v.shape==(750,) and np.isfinite(v).all(),'Head shape/finiteness');heads.append(v)
 feature=np.column_stack(heads);require(np.allclose(mix(corr,feature,oldw,True),historical_raw,atol=1e-12,rtol=0),'Frozen blind H6 head does not reconstruct historical raw mixture');ops={x['context']:x for x in json.loads(Path(files['original_operator']['path']).read_text())};op=ops['blind750'];placement=json.loads(Path(files['blind750_original_calibration']['path']).read_text());require(op['calibration']==placement['calibration'],'Serving constants mismatch');mu=np.asarray(op['original_raw_reference_mean']);require(np.allclose(mu,original.mean(0),atol=1e-12,rtol=0),'Original reference mean mismatch');map_original=lambda a:fixed_map(a,mu,op['calibration'],op['floor']);lambda0=map_original(mix(original,feature,np.zeros(4),True));zero_error=float(abs(lambda0-incumbent).max());require(zero_error<=1e-12,'Lambda0 does not reconstruct original served values');require(files['blind750_original_served']['sha256']=='349165ecf50906e43a27f12dee97891a92cda59e798db614ef27a7c920c38a37','Wrong incumbent');raw=mix(original,feature,weights,True);served=map_original(raw)
 validator_spec=importlib.util.spec_from_file_location('p5b_candidate_validator',files['validator']['path']);validator=importlib.util.module_from_spec(validator_spec);validator_spec.loader.exec_module(validator);validation={}
 for lane,values in [('raw',raw),('served',served)]:
  require(values.shape==(750,4) and np.isfinite(values).all() and np.all(values.std(0,ddof=1)>=.01),'Finite/spread failure');frame=blind[['SMILES','Molecule_Name']].copy()
  for j,target in enumerate(T):frame[target]=values[:,j]
  path=out/f'incumbent-anchored-H6-{lane}-PRIVATE.csv';frame.to_csv(path,index=False,float_format='%.17g');reread=pd.read_csv(path);require(reread.Molecule_Name.tolist()==qids and reread.SMILES.tolist()==blind.SMILES.tolist(),'Candidate identity changed');require(list(reread.columns)==['SMILES','Molecule_Name']+T,'Column schema');ok,errors=validator.validate_activity_submission(path,expected_ids=set(qids));require(ok,str(errors));validation[lane]={'path':str(path),'sha256':sha(path),'rows':750,'exact_ID_SMILES_order':True,'finite':True,'sample_std':values.std(0,ddof=1).tolist(),'std_threshold':.01,'pinned_official_validator_passed':True,'validator_sha256':files['validator']['sha256']}
 control=out/'lambda0-original-incumbent-CONTROL.csv';shutil.copyfile(files['blind750_original_served']['path'],control);require(sha(control)==files['blind750_original_served']['sha256'],'Incumbent control bytes changed');save(out/'LAMBDA0_CONTROL.json',{'numeric_operator_max_abs_error':zero_error,'numeric_tolerance':1e-12,'byte_identical_control_sha256':sha(control),'original_artifact_preserved':True,'no_per_row_corrections':True});save(out/'SERVING_OPERATOR.json',{'source':files['operator_source'],'original_placement':files['blind750_original_calibration'],'frozen_numeric_operator':op,'reference_mean_frozen':mu.tolist(),'candidate_dependent_calibration':False})
 comparisons=[]
 for reference_name,reference in [('best_incumbent_349165',incumbent),('bad_last_H6_91fa8b',badlast)]:
  for j,target in enumerate(T):
   delta=served[:,j]-reference[:,j];comparisons.append({'reference':reference_name,'target':target,'mean_abs_prediction_difference':float(abs(delta).mean()),'RMSE_between_predictions_not_true_error':float(np.sqrt(np.mean(delta**2))),'max_abs_difference':float(abs(delta).max()),'candidate_mean':float(served[:,j].mean()),'reference_mean':float(reference[:,j].mean()),'candidate_sample_SD':float(served[:,j].std(ddof=1)),'reference_sample_SD':float(reference[:,j].std(ddof=1)),'Pearson_between_predictions':float(pearsonr(served[:,j],reference[:,j]).statistic),'Spearman_between_predictions':float(spearmanr(served[:,j],reference[:,j]).statistic),'candidate_floor_fraction':float((served[:,j]==op['floor']).mean())})
 pd.DataFrame(comparisons).to_csv(out/'UNLABELED_COMPARISON.csv',index=False);save(out/'VALIDATION.json',validation);save(out/'COMPLETE.json',{'status':'ready_for_PRIVATE_REVIEW_ONLY','seconds':time.monotonic()-start,'full_training_rows':4905,'blind_rows':750,'coefficient_fits':4,'base_fits':0,'feature_changes':0,'calibration_fits':0,'weights':coef['weights'],'validation':validation,'lambda0_max_abs_error':zero_error,'incumbent_sha256':files['blind750_original_served']['sha256'],'bad_last_submission_sha256':files['bad_last_submission']['sha256'],'candidate_score_unknown':True,'not_promoted':True,'human_explicit_approval_required_for_any_public_dispatch':True,'no_publication':True,'no_submission':True,'historical_H6_OOF_reconstruction_error':float(abs(historical_OOF-historical_H6).max()),'input_manifest':c['manifest'],'scorer_sha256':c['scorer_sha256'],'source_sha256':sha(__file__),'file_hashes':{f.name:sha(f) for f in out.iterdir() if f.is_file()}});print(json.dumps({'status':'ready_for_PRIVATE_REVIEW_ONLY','seconds':time.monotonic()-start,'weights':coef['weights'],'candidate':validation['served'],'lambda0_error':zero_error,'base_fits':0,'no_publication_or_submission':True}),flush=True)
if __name__=='__main__':main()
